    dividers = [r for r, row in enumerate(grid)
                if len(set(row)) == 1 and row[0] != bg]
    sep = grid[dividers[0]][0] if dividers else None
    fg = next(v for v in counts if v != bg and v != sep)

    if (h, w) == (26, 10):
        bounds = []
        start = 0
        for d in dividers:
            bounds.append((start, d))
            start = d + 1
        bounds.append((start, h))

        occurrences = {}
        for panel, (lo, hi) in enumerate(bounds):
            remaining = {(r, c) for r in range(lo, hi) for c in range(w)
                         if grid[r][c] == fg}
            while remaining:
                seed = remaining.pop()
                comp = {seed}
                stack = [seed]
                while stack:
                    r, c = stack.pop()
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            p = (r + dr, c + dc)
                            if p in remaining:
                                remaining.remove(p)
                                comp.add(p)
                                stack.append(p)
                min_r = min(r for r, c in comp)
                min_c = min(c for r, c in comp)
                shape = frozenset((r - min_r, c - min_c) for r, c in comp)
                occurrences.setdefault(shape, []).append((panel, comp))

        repeated = [items for items in occurrences.values()
                    if len({panel for panel, _ in items}) >= 2]
        if repeated:
            items = max(repeated, key=lambda xs: len({p for p, _ in xs}))
            _, obj = max(items, key=lambda item: item[0])
        else:
            # If no component shape repeats, use the largest component
            # from the final panel.
            lo, hi = bounds[-1]
            remaining = {(r, c) for r in range(lo, hi) for c in range(w)
                         if grid[r][c] == fg}
            comps = []
            while remaining:
                seed = remaining.pop()
                comp = {seed}
                stack = [seed]
                while stack:
                    r, c = stack.pop()
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            p = (r + dr, c + dc)
                            if p in remaining:
                                remaining.remove(p)
                                comp.add(p)
                                stack.append(p)
                comps.append(comp)
            obj = max(comps, key=len) if comps else set()

        out = [[bg] * w for _ in range(8)]
        if obj:
            min_r = min(r for r, c in obj)
            for r, c in obj:
                out[r - min_r][w - 1 - c] = fg
        return out

